import React, { useState, useMemo } from 'react';
import { 
  Trash2, Plus, Play, Clock, Calendar, Download, 
  ShieldCheck, Globe, Home, BookOpen, ChevronRight, Settings2, Users, RefreshCw, CheckCircle2, AlertCircle
} from 'lucide-react';

// --- HELPER FUNCTIONS ---
const formatTime = (timeStr) => {
  if (!timeStr) return "";
  const [h, m] = timeStr.split(':').map(Number);
  const suffix = h >= 12 ? 'PM' : 'AM';
  const displayH = h % 12 || 12;
  return `${displayH}:${String(m).padStart(2, '0')} ${suffix}`;
};

const addHours = (time, hours) => {
  const [h, m] = time.split(':').map(Number);
  const totalH = h + hours;
  return `${String(totalH).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const DepartmentCard = ({ 
  dept, 
  onUpdate, 
  onGenerate, 
  onDeleteDept, 
  onClearSchedule, 
  globalSchedule = [], 
  allDepartments = [] 
}) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const [generationErrors, setGenerationErrors] = useState([]); 
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // --- STATUS & PREVIEW ENGINE ---
  const consolidatedPreview = useMemo(() => {
    const deptData = globalSchedule.filter(s => s.dept_code === deptCode);
    const groups = {};
    const today = new Date().toISOString().split('T')[0];

    deptData.forEach(item => {
      const groupKey = `${item.section}-${item.exam_date}`;
      if (!groups[groupKey]) {
        let currentStatus = item.status || 'COMMITTED';
        if (item.exam_date < today) currentStatus = 'DONE';

        groups[groupKey] = {
          section: item.section,
          date: item.exam_date,
          year: item.year_level,
          room: item.room,
          proctor: item.proctor,
          status: currentStatus, 
          startTime: item.start_time,
          endTime: item.end_time,
          subs: []
        };
      }
      groups[groupKey].subs.push({
        code: item.subject_code,
        name: item.subject_name,
        slot: `${formatTime(item.start_time)} - ${formatTime(item.end_time)}`
      });
      if (item.start_time < groups[groupKey].startTime) groups[groupKey].startTime = item.start_time;
      if (item.end_time > groups[groupKey].endTime) groups[groupKey].endTime = item.end_time;
    });

    return Object.values(groups).sort((a, b) => new Date(a.date) - new Date(b.date));
  }, [globalSchedule, deptCode]);

  // --- GENERATOR UI STATES ---
  const [examDays, setExamDays] = useState(0); 
  const [examDates, setExamDates] = useState([]);
  const [startTime, setStartTime] = useState("08:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(0); 
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");

  // --- INPUT STATES ---
  const [pName, setPName] = useState("");
  const [pDayStart, setPDayStart] = useState("");
  const [pDayEnd, setPDayEnd] = useState("");
  const [pTimeStart, setPTimeStart] = useState("08:00");
  const [pTimeEnd, setPTimeEnd] = useState("17:00");
  const [roomNum, setRoomNum] = useState("");
  const [roomType, setRoomType] = useState("Department");

  const globalProctorPool = useMemo(() => allDepartments.flatMap(d => d.proctors), [allDepartments]);
  const globalRoomPool = useMemo(() => allDepartments.flatMap(d => d.rooms), [allDepartments]);

  const handleExamDayChange = (val) => {
    const num = parseInt(val) || 0;
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  // --- INTEGRATED VALIDATION & GENERATION ---
  const handleGenerateClick = () => {
    setGenerationErrors([]);
    const errors = [];
    const yearSubs = subjects[selectedYear] || [];

    if (yearSubs.length === 0) errors.push({ issue: "No Subjects", resolution: `Add subjects for Year ${selectedYear} first.` });
    if (examDays === 0 || sectionCount === 0) errors.push({ issue: "Config Error", resolution: "Set Exam Days and Section Count." });
    if (examDates.some(d => !d)) errors.push({ issue: "Missing Timeline", resolution: "Assign a date to every exam day." });

    if (errors.length > 0) {
      setGenerationErrors(errors);
      return; 
    }

    const shuffled = [...yearSubs].sort(() => Math.random() - 0.5);
    const dailySubs = Array.from({ length: examDays }, () => []);
    shuffled.forEach((s, i) => dailySubs[i % examDays].push(s));

    const finalGeneratedData = [];

    // FIXED: Counters to rotate through available resources instead of picking index 0
    let proctorIndex = 0;
    let roomIndex = 0;

    for (let d = 0; d < examDays; d++) {
      const dayDate = examDates[d];
      const daySubjects = dailySubs[d];
      const duration = daySubjects.length;
      const endTime = addHours(startTime, duration);

      // Filter available rooms for this specific time window
      const isRoomFree = (rNum) => !globalSchedule.some(gs => gs.room === rNum && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time));
      const localRooms = rooms.filter(r => isRoomFree(r.number));
      const otherRooms = globalRoomPool.filter(r => !rooms.find(dr => dr.number === r.number) && isRoomFree(r.number));
      let availableRooms = roomSource === "Department" ? [...localRooms, ...otherRooms] : [...otherRooms, ...localRooms];

      // Filter available proctors for this specific time window
      const getAvailableProctors = (pool) => pool.filter(p => 
          dayDate >= p.dayStart && dayDate <= p.dayEnd &&
          startTime >= p.timeStart && endTime <= p.timeEnd &&
          !globalSchedule.some(gs => gs.proctor === p.name && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time))
      );

      let availableProctors = getAvailableProctors(proctorSource === "Department" ? proctors : globalProctorPool);
      if (availableProctors.length === 0 && proctorSource === "Department") {
          availableProctors = getAvailableProctors(globalProctorPool);
      }

      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`;

        // FIXED: Use Modulo (%) to cycle through the list of available rooms/proctors
        const selectedRoom = availableRooms[roomIndex % availableRooms.length];
        const selectedProctor = availableProctors[proctorIndex % availableProctors.length];

        if (!selectedRoom) {
            errors.push({ 
              issue: `Room Shortage (Day ${d+1})`, 
              resolution: `You need ${sectionCount} rooms, but only ${availableRooms.length} are free.` 
            });
        }

        if (!selectedProctor) {
            errors.push({ 
              issue: `Staffing Blocker (Day ${d+1})`, 
              resolution: "Insufficient available proctors for this shift." 
            });
        }

        if (errors.length === 0) {
            daySubjects.forEach((sub, idx) => {
              finalGeneratedData.push({
                subject_code: sub.code, subject_name: sub.name, section: sectionID,
                year_level: selectedYear, dept_code: deptCode, exam_date: dayDate,
                start_time: addHours(startTime, idx), end_time: addHours(startTime, idx + 1),
                room: selectedRoom.number, proctor: selectedProctor.name,
                status: 'ACTIVE'
              });
            });
            // Increment indices so the next section gets the next room/proctor
            proctorIndex++;
            roomIndex++;
        }
      }
