                                {row.subs.map((s, idx) => (
                                    <div key={idx} className="bg-white p-6 rounded-3xl border-2 border-white shadow-sm group-hover:border-blue-100 transition-all flex flex-col justify-between hover:shadow-md">
                                        <div className="flex justify-between items-start">
                                            <span className="text-sm font-black text-blue-600">{s.code}</span>
                                            <span className="text-[9px] font-black text-slate-400 uppercase italic tracking-tighter">{s.slot}</span>
                                        </div>
                                        <p className="text-[11px] font-black text-slate-800 uppercase mt-4 leading-snug">{s.name}</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )) : (
                    <div className="text-center py-32 bg-slate-50 rounded-[4rem] border-4 border-dashed border-slate-100">
                        <RefreshCw size={48} className="text-slate-200 mx-auto mb-6 animate-spin-slow" />
                        <p className="text-slate-300 font-black uppercase tracking-[0.4em] text-xs">No active draft found in system memory</p>
                    </div>
                )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
